    pub fn scene_index_name_contains_value(
        resource: ResourceArc<SceneIndexResource>,
        needle: String,
    ) -> Vec<SceneQueryNode> {
        let index = resource.index.clone();
        scene_query_nodes_matching(
            &index,
            |node| { node.name.as_ref().is_some_and(|name| name.contains(&needle)) },
        )
    }
